
-- BATCH: Global Recipes from All Continents
-- Asia (40 recipes), Europe (30 recipes), South America (20 recipes), North America (20 recipes), Oceania (10 recipes)

INSERT INTO recipes (name, slug, country, continent, category, summary, history, difficulty, prep_time, cook_time, servings, calories, protein, carbs, fats, tags, is_african, image_url, ingredients, steps) VALUES

-- ===== ASIA =====
-- Japan
('Miso Soup','miso-soup','Japan','Asia','Breakfast','A traditional Japanese soup consisting of dashi stock with softened miso paste and various ingredients like tofu, wakame seaweed, and green onions.','Miso soup dates back to the Muromachi period (1336-1573) and became a staple of Japanese cuisine during the Edo period. It is considered essential to a traditional Japanese breakfast and is believed to promote longevity.',
'Easy',5,10,4,84,6,8,3,'{"breakfast","japanese","soup","traditional","healthy"}',false,
'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=800',
'[{"item":"white miso paste","amount":"3 tbsp"},{"item":"dashi stock","amount":"4 cups"},{"item":"silken tofu","amount":"200g"},{"item":"wakame seaweed","amount":"2 tbsp"},{"item":"green onions","amount":"2 stalks"}]',
'[{"step":1,"instruction":"Bring dashi stock to a gentle simmer in a pot."},{"step":2,"instruction":"Cut tofu into small cubes. Rehydrate wakame in water for 5 minutes."},{"step":3,"instruction":"Dissolve miso paste in a ladle of warm dashi, then stir into the pot. Do not boil after adding miso."},{"step":4,"instruction":"Add tofu and wakame, heat gently for 2 minutes."},{"step":5,"instruction":"Serve in bowls garnished with sliced green onions."}]'),

('Tonkotsu Ramen','tonkotsu-ramen','Japan','Asia','Dinner','Rich, creamy pork bone broth ramen with chashu pork, soft-boiled egg, and noodles — the iconic comfort food of Fukuoka.','Tonkotsu ramen originated in Fukuoka in 1937 when Tokio Miyamoto served the first bowl at his Nankin Senryo stall. The style spread across Kyushu and became Japan''s most internationally recognized ramen variety.',
'Hard',30,720,4,550,28,65,18,'{"dinner","japanese","ramen","noodles","comfort food"}',false,
'https://images.unsplash.com/photo-1569718212165-3a8278d5f624?w=800',
'[{"item":"pork bones","amount":"2 kg"},{"item":"ramen noodles","amount":"400g"},{"item":"chashu pork belly","amount":"300g"},{"item":"soft-boiled eggs","amount":"4"},{"item":"green onions","amount":"4 stalks"},{"item":"garlic","amount":"6 cloves"},{"item":"ginger","amount":"1 piece"},{"item":"soy sauce","amount":"4 tbsp"},{"item":"sesame oil","amount":"1 tbsp"}]',
'[{"step":1,"instruction":"Boil pork bones vigorously for 12 hours, adding water as needed, until broth is opaque and creamy."},{"step":2,"instruction":"Braise pork belly in soy sauce, mirin, and sake for 2 hours until tender. Slice thinly."},{"step":3,"instruction":"Prepare soft-boiled eggs (6.5 min) and marinate in soy-mirin mixture."},{"step":4,"instruction":"Cook ramen noodles according to package directions."},{"step":5,"instruction":"Assemble: broth in bowl, noodles, chashu, egg, green onions, and sesame oil."}]'),

('Matcha Latte','matcha-latte','Japan','Asia','Drinks','Ceremonial-grade matcha whisked with steamed milk — a modern take on centuries-old Japanese tea tradition.','Matcha was brought to Japan from China by Zen monk Eisai in 1191. The tea ceremony (chanoyu) became central to Japanese culture. The modern matcha latte emerged in the 2000s as Japanese café culture blended with Western coffee traditions.',
'Easy',5,5,1,120,4,15,4,'{"drinks","japanese","tea","matcha","healthy"}',false,
'https://images.unsplash.com/photo-1515823064-d6e0c04616a7?w=800',
'[{"item":"ceremonial matcha powder","amount":"2 tsp"},{"item":"hot water","amount":"60ml"},{"item":"milk","amount":"240ml"},{"item":"honey or sugar","amount":"1 tsp"}]',
'[{"step":1,"instruction":"Sift matcha powder into a bowl to remove lumps."},{"step":2,"instruction":"Add hot water (80°C) and whisk vigorously with a bamboo chasen until frothy."},{"step":3,"instruction":"Heat and froth milk until steamy."},{"step":4,"instruction":"Pour matcha into a cup, add sweetener, then top with steamed milk."}]'),

('Japanese Curry Rice','japanese-curry-rice','Japan','Asia','Dinner','A thick, mildly sweet curry served over steamed rice — Japan''s most popular comfort food, eaten by millions weekly.','Japanese curry was introduced by the British Royal Navy in the late 1800s via Indian curry. The Japanese adapted it with sweeter, thicker sauce. S&B and House Foods commercialized curry roux blocks in the 1950s, making it a household staple.',
'Easy',15,45,4,480,22,62,14,'{"dinner","japanese","curry","comfort food","rice"}',false,
'https://images.unsplash.com/photo-1604908176997-125f25cc6f3d?w=800',
'[{"item":"chicken thigh","amount":"400g"},{"item":"potatoes","amount":"2 large"},{"item":"carrots","amount":"2"},{"item":"onions","amount":"2"},{"item":"curry roux blocks","amount":"1 package"},{"item":"water","amount":"800ml"},{"item":"steamed rice","amount":"4 cups"},{"item":"vegetable oil","amount":"2 tbsp"}]',
'[{"step":1,"instruction":"Cut chicken, potatoes, carrots, and onions into bite-sized pieces."},{"step":2,"instruction":"Sauté onions in oil until translucent, add chicken and cook through."},{"step":3,"instruction":"Add carrots and potatoes, pour in water, bring to boil and simmer 20 minutes."},{"step":4,"instruction":"Turn off heat, add curry roux blocks, stir until dissolved."},{"step":5,"instruction":"Simmer on low for 10 more minutes until thickened. Serve over steamed rice."}]'),

-- India
('Masala Dosa','masala-dosa','India','Asia','Breakfast','Crispy fermented rice and lentil crepe filled with spiced potato filling, served with sambar and coconut chutney.','Dosa originated in South India over 2,000 years ago, with mentions in Sangam literature. Masala dosa, with its potato filling, became popularized in Udupi restaurants of Karnataka in the early 20th century and spread globally through the Indian diaspora.',
'Medium',30,20,4,350,10,55,8,'{"breakfast","indian","south indian","vegetarian","fermented"}',false,
'https://images.unsplash.com/photo-1668236543090-82eb5eace6d2?w=800',
'[{"item":"dosa batter (rice and urad dal)","amount":"2 cups"},{"item":"potatoes","amount":"3 large"},{"item":"onions","amount":"2"},{"item":"mustard seeds","amount":"1 tsp"},{"item":"curry leaves","amount":"10"},{"item":"turmeric","amount":"1/2 tsp"},{"item":"green chilies","amount":"3"},{"item":"ghee","amount":"3 tbsp"}]',
'[{"step":1,"instruction":"Boil and mash potatoes. Temper mustard seeds, curry leaves, and green chilies in oil. Add onions and turmeric, then fold in potatoes."},{"step":2,"instruction":"Heat a flat griddle (tawa). Pour a ladleful of batter and spread in a circular motion to make a thin crepe."},{"step":3,"instruction":"Drizzle ghee around edges, cook until golden and crispy."},{"step":4,"instruction":"Place potato filling in the center, fold dosa over it."},{"step":5,"instruction":"Serve hot with coconut chutney and sambar."}]'),

('Butter Chicken','butter-chicken','India','Asia','Dinner','Tender chicken in a rich, creamy tomato-based sauce with aromatic spices — India''s most famous curry worldwide.','Butter chicken (Murgh Makhani) was created in the 1950s by Kundan Lal Gujral at Moti Mahal restaurant in Delhi. He repurposed leftover tandoori chicken in a tomato-cream gravy, accidentally creating one of the world''s most beloved dishes.',
'Medium',20,40,4,490,35,12,32,'{"dinner","indian","curry","chicken","north indian"}',false,
'https://images.unsplash.com/photo-1603894584373-5ac82b2ae398?w=800',
'[{"item":"chicken thighs","amount":"600g"},{"item":"yogurt","amount":"1 cup"},{"item":"tomato puree","amount":"400g"},{"item":"heavy cream","amount":"1/2 cup"},{"item":"butter","amount":"4 tbsp"},{"item":"garam masala","amount":"2 tsp"},{"item":"kashmiri red chili powder","amount":"2 tsp"},{"item":"ginger-garlic paste","amount":"2 tbsp"},{"item":"fenugreek leaves","amount":"1 tsp"},{"item":"sugar","amount":"1 tsp"}]',
'[{"step":1,"instruction":"Marinate chicken in yogurt, chili powder, and ginger-garlic paste for 2 hours minimum."},{"step":2,"instruction":"Grill or pan-fry marinated chicken until charred."},{"step":3,"instruction":"In a pot, melt butter, add tomato puree, and cook for 15 minutes until oil separates."},{"step":4,"instruction":"Add garam masala, sugar, and fenugreek. Stir in cream."},{"step":5,"instruction":"Add chicken pieces, simmer for 15 minutes. Finish with a knob of butter."}]'),

('Chai','masala-chai','India','Asia','Drinks','Spiced Indian tea brewed with milk, sugar, and a blend of aromatic spices — the world''s most consumed spiced beverage.','Chai has been part of Indian culture for millennia, but the modern spiced milk tea emerged during British colonial rule when the British India Tea Association promoted tea consumption. Street chai wallahs created the iconic spiced version that became India''s national drink.',
'Easy',5,10,2,120,3,18,4,'{"drinks","indian","tea","spiced","traditional"}',false,
'https://images.unsplash.com/photo-1597318181409-cf64d0b5d8a2?w=800',
'[{"item":"black tea leaves (Assam)","amount":"2 tbsp"},{"item":"whole milk","amount":"1 cup"},{"item":"water","amount":"1 cup"},{"item":"sugar","amount":"2 tbsp"},{"item":"cardamom pods","amount":"4"},{"item":"cinnamon stick","amount":"1"},{"item":"ginger","amount":"1 inch piece"},{"item":"cloves","amount":"2"}]',
'[{"step":1,"instruction":"Crush cardamom pods and slice ginger. Add water, spices, and ginger to a saucepan."},{"step":2,"instruction":"Bring to a boil, add tea leaves, and simmer for 3 minutes."},{"step":3,"instruction":"Add milk and sugar, bring to a rolling boil."},{"step":4,"instruction":"Strain into cups and serve immediately."}]'),

('Biryani','hyderabadi-biryani','India','Asia','Lunch','Fragrant layered rice dish with marinated meat, saffron, and aromatic spices — the crown jewel of Mughlai cuisine.','Biryani''s origins are debated — some trace it to Persia, others to the Mughals. Hyderabadi biryani was perfected in the Nizam''s kitchen in the 18th century using the dum (slow-cooking) method. Each Indian city has its own signature style.',
'Hard',40,60,6,580,30,65,18,'{"lunch","indian","rice","mughlai","festive"}',false,
'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?w=800',
'[{"item":"basmati rice","amount":"3 cups"},{"item":"lamb or chicken","amount":"750g"},{"item":"yogurt","amount":"1 cup"},{"item":"onions","amount":"4 large"},{"item":"saffron","amount":"1/2 tsp"},{"item":"warm milk","amount":"1/4 cup"},{"item":"mint leaves","amount":"1 cup"},{"item":"ghee","amount":"4 tbsp"},{"item":"biryani masala","amount":"3 tbsp"},{"item":"fried onions","amount":"1 cup"}]',
'[{"step":1,"instruction":"Marinate meat in yogurt, biryani masala, ginger-garlic paste, and half the mint for 2 hours."},{"step":2,"instruction":"Parboil rice with whole spices until 70% cooked. Drain."},{"step":3,"instruction":"Layer marinated meat, then rice, then saffron milk, fried onions, and remaining mint."},{"step":4,"instruction":"Seal pot with dough or foil. Cook on very low heat (dum) for 45 minutes."},{"step":5,"instruction":"Gently mix layers when serving. Garnish with fried onions and fresh mint."}]'),

-- China
('Xiaolongbao','xiaolongbao','China','Asia','Lunch','Delicate steamed soup dumplings filled with seasoned pork and rich, hot broth — Shanghai''s most iconic dim sum.','Xiaolongbao originated in Nanxiang, a suburb of Shanghai, in the 1870s at Ri Hua Xuan restaurant. The technique of encasing gelatinized broth inside the dumpling wrapper revolutionized Chinese dumpling-making.',
'Hard',60,15,4,420,22,48,16,'{"lunch","chinese","dumplings","dim sum","shanghai"}',false,
'https://images.unsplash.com/photo-1496116218417-1a781b1c416c?w=800',
'[{"item":"all-purpose flour","amount":"300g"},{"item":"ground pork","amount":"300g"},{"item":"pork skin jelly (aspic)","amount":"200g"},{"item":"ginger","amount":"2 tbsp minced"},{"item":"soy sauce","amount":"2 tbsp"},{"item":"sesame oil","amount":"1 tbsp"},{"item":"shaoxing wine","amount":"1 tbsp"},{"item":"green onions","amount":"3 stalks"}]',
'[{"step":1,"instruction":"Make dough: mix flour and hot water, knead until smooth, rest 30 minutes."},{"step":2,"instruction":"Mix pork with soy sauce, sesame oil, ginger, wine, and chopped green onions."},{"step":3,"instruction":"Dice pork skin jelly finely and fold into filling."},{"step":4,"instruction":"Roll dough into thin wrappers. Place filling in center, pleat edges to seal (18 folds traditional)."},{"step":5,"instruction":"Steam in bamboo steamer lined with cabbage leaves for 8-10 minutes. Serve with black vinegar and ginger."}]'),

('Kung Pao Chicken','kung-pao-chicken','China','Asia','Dinner','Spicy stir-fried chicken with peanuts, vegetables, and dried chilies — a beloved Sichuan classic with perfect balance of heat and sweetness.','Named after Ding Baozhen, a Qing Dynasty governor of Sichuan province (titled Gong Bao), this dish was created by his personal chef in the 19th century. It survived the Cultural Revolution (when it was renamed) and is now one of China''s most recognized dishes globally.',
'Medium',15,10,4,380,28,18,22,'{"dinner","chinese","sichuan","spicy","stir-fry"}',false,
'https://images.unsplash.com/photo-1525755662778-989d0524087e?w=800',
'[{"item":"chicken breast","amount":"500g"},{"item":"roasted peanuts","amount":"1/2 cup"},{"item":"dried red chilies","amount":"12"},{"item":"Sichuan peppercorns","amount":"1 tsp"},{"item":"soy sauce","amount":"2 tbsp"},{"item":"rice vinegar","amount":"1 tbsp"},{"item":"sugar","amount":"1 tbsp"},{"item":"cornstarch","amount":"1 tbsp"},{"item":"garlic","amount":"4 cloves"},{"item":"green onions","amount":"4 stalks"}]',
'[{"step":1,"instruction":"Cut chicken into cubes, marinate with soy sauce and cornstarch for 15 minutes."},{"step":2,"instruction":"Heat wok until smoking. Add oil, dried chilies, and Sichuan peppercorns until fragrant."},{"step":3,"instruction":"Add chicken, stir-fry until golden. Add garlic."},{"step":4,"instruction":"Add sauce mixture (soy sauce, vinegar, sugar, cornstarch slurry)."},{"step":5,"instruction":"Toss in peanuts and green onions. Serve immediately over steamed rice."}]'),

('Dim Sum Har Gow','har-gow-shrimp-dumplings','China','Asia','Lunch','Crystal-skinned shrimp dumplings — the gold standard of Cantonese dim sum craftsmanship.','Har gow originated in a small teahouse in the Wucu village near Guangzhou in the 1920s. The translucent wheat starch wrapper and precisely minced shrimp filling became the benchmark by which dim sum chefs are judged.',
'Hard',45,10,4,280,18,30,8,'{"lunch","chinese","dim sum","cantonese","dumplings"}',false,
'https://images.unsplash.com/photo-1576577445504-6af96477db52?w=800',
'[{"item":"shrimp","amount":"400g"},{"item":"wheat starch","amount":"150g"},{"item":"tapioca starch","amount":"50g"},{"item":"bamboo shoots","amount":"50g"},{"item":"pork fat","amount":"30g"},{"item":"sesame oil","amount":"1 tsp"},{"item":"white pepper","amount":"1/4 tsp"},{"item":"salt","amount":"1/2 tsp"}]',
'[{"step":1,"instruction":"Peel and devein shrimp. Roughly chop half, finely mince the rest for texture contrast."},{"step":2,"instruction":"Mix shrimp with diced bamboo shoots, pork fat, sesame oil, pepper, and salt."},{"step":3,"instruction":"Make wrapper dough: pour boiling water over wheat and tapioca starch, knead until smooth."},{"step":4,"instruction":"Roll thin wrappers, fill with shrimp mixture, and pleat into crescent shape (7+ pleats)."},{"step":5,"instruction":"Steam in bamboo steamer for 6-8 minutes until wrappers turn translucent."}]'),

-- Thailand
('Pad Thai','pad-thai','Thailand','Asia','Dinner','Stir-fried rice noodles with shrimp, tofu, bean sprouts, peanuts, and tamarind sauce — Thailand''s national dish.','Pad Thai was created during WWII as part of Prime Minister Phibunsongkhram''s nation-building campaign to reduce rice consumption and promote Thai identity. The government distributed the recipe nationwide, and it became the country''s most famous culinary export.',
'Medium',15,10,4,450,20,52,18,'{"dinner","thai","noodles","stir-fry","street food"}',false,
'https://images.unsplash.com/photo-1559314809-0d155014e29e?w=800',
'[{"item":"rice noodles","amount":"250g"},{"item":"shrimp","amount":"200g"},{"item":"firm tofu","amount":"150g"},{"item":"eggs","amount":"2"},{"item":"bean sprouts","amount":"1 cup"},{"item":"tamarind paste","amount":"3 tbsp"},{"item":"fish sauce","amount":"3 tbsp"},{"item":"palm sugar","amount":"2 tbsp"},{"item":"roasted peanuts","amount":"1/4 cup"},{"item":"lime","amount":"2"},{"item":"garlic chives","amount":"1/2 cup"}]',
'[{"step":1,"instruction":"Soak rice noodles in warm water for 30 minutes until pliable. Drain."},{"step":2,"instruction":"Mix tamarind paste, fish sauce, and palm sugar for the sauce."},{"step":3,"instruction":"Stir-fry tofu cubes until golden, then add shrimp and cook through."},{"step":4,"instruction":"Push to side, scramble eggs, then add noodles and sauce. Toss everything together."},{"step":5,"instruction":"Add bean sprouts and chives. Serve with crushed peanuts and lime wedges."}]'),

('Tom Yum Goong','tom-yum-goong','Thailand','Asia','Dinner','Hot and sour Thai soup with shrimp, lemongrass, galangal, and lime — an explosion of quintessential Thai flavors.','Tom Yum originated in central Thailand and reflects the Thai culinary philosophy of balancing sour, salty, spicy, and sweet. The creamy version (Tom Yum Goong Nam Khon) was submitted for UNESCO Intangible Cultural Heritage status in 2024.',
'Medium',10,15,4,180,18,8,8,'{"dinner","thai","soup","spicy","seafood"}',false,
'https://images.unsplash.com/photo-1548943487-a2e4e43b4853?w=800',
'[{"item":"large shrimp","amount":"400g"},{"item":"lemongrass","amount":"3 stalks"},{"item":"galangal","amount":"5 slices"},{"item":"kaffir lime leaves","amount":"5"},{"item":"Thai bird chilies","amount":"5"},{"item":"fish sauce","amount":"3 tbsp"},{"item":"lime juice","amount":"3 tbsp"},{"item":"mushrooms","amount":"200g"},{"item":"coconut milk","amount":"1/2 cup"},{"item":"cilantro","amount":"1/4 cup"}]',
'[{"step":1,"instruction":"Bruise lemongrass and tear kaffir lime leaves. Bring water or stock to boil with lemongrass, galangal, and lime leaves."},{"step":2,"instruction":"Add mushrooms and chilies, simmer 5 minutes."},{"step":3,"instruction":"Add shrimp, cook until pink (2-3 minutes)."},{"step":4,"instruction":"Remove from heat. Stir in fish sauce, lime juice, and coconut milk."},{"step":5,"instruction":"Garnish with cilantro and serve immediately."}]'),

('Thai Iced Tea','thai-iced-tea','Thailand','Asia','Drinks','Vibrant orange Thai tea sweetened with condensed milk and poured over ice — an iconic Southeast Asian refreshment.','Thai tea (Cha Yen) became popular in Thailand during the 1980s-90s. The distinctive orange color comes from food coloring added to strongly brewed Ceylon tea. It evolved from Chinese tea traditions brought by immigrants and became a beloved Thai street drink.',
'Easy',5,5,2,200,4,35,6,'{"drinks","thai","tea","iced","sweet"}',false,
'https://images.unsplash.com/photo-1556679343-c7306c1976bc?w=800',
'[{"item":"Thai tea mix","amount":"4 tbsp"},{"item":"water","amount":"2 cups"},{"item":"sweetened condensed milk","amount":"3 tbsp"},{"item":"evaporated milk","amount":"2 tbsp"},{"item":"sugar","amount":"2 tbsp"},{"item":"ice","amount":"2 cups"}]',
'[{"step":1,"instruction":"Brew Thai tea mix in boiling water for 5 minutes. Strain through a cloth filter."},{"step":2,"instruction":"Add sugar and condensed milk to hot tea, stir until dissolved."},{"step":3,"instruction":"Let cool to room temperature."},{"step":4,"instruction":"Fill glasses with ice, pour tea over ice, top with a splash of evaporated milk."}]'),

-- South Korea
('Bibimbap','bibimbap','South Korea','Asia','Lunch','A colorful Korean rice bowl topped with sautéed vegetables, gochujang, a fried egg, and optional meat — harmony in a bowl.','Bibimbap''s origins trace to the Joseon Dynasty (1392-1897), where it was served as a royal court dish. Jeonju bibimbap is considered the gold standard. The dish embodies the Korean philosophy of balancing five colors representing five elements.',
'Medium',30,15,4,520,25,68,14,'{"lunch","korean","rice bowl","vegetables","healthy"}',false,
'https://images.unsplash.com/photo-1553163147-622ab57be1c7?w=800',
'[{"item":"steamed rice","amount":"4 cups"},{"item":"spinach","amount":"200g"},{"item":"bean sprouts","amount":"200g"},{"item":"carrots","amount":"2"},{"item":"zucchini","amount":"1"},{"item":"shiitake mushrooms","amount":"150g"},{"item":"ground beef","amount":"200g"},{"item":"gochujang","amount":"4 tbsp"},{"item":"sesame oil","amount":"2 tbsp"},{"item":"eggs","amount":"4"},{"item":"sesame seeds","amount":"2 tbsp"}]',
'[{"step":1,"instruction":"Prepare each vegetable separately: blanch spinach and bean sprouts, sauté carrots, zucchini, and mushrooms with garlic and sesame oil."},{"step":2,"instruction":"Season and cook ground beef with soy sauce and sesame oil."},{"step":3,"instruction":"Fry eggs sunny-side up."},{"step":4,"instruction":"Arrange rice in bowls, artfully place each vegetable and meat in sections around the bowl."},{"step":5,"instruction":"Top with fried egg, gochujang, and sesame seeds. Mix everything together before eating."}]'),

('Kimchi Jjigae','kimchi-jjigae','South Korea','Asia','Dinner','A robust, spicy Korean stew made with fermented kimchi, pork, and tofu — Korea''s ultimate comfort food.','Kimchi jjigae evolved naturally from Korea''s ancient kimchi-making tradition. As kimchi ages and becomes more sour, Koreans developed this stew as the perfect way to use well-fermented kimchi. It became a daily household staple in the 20th century.',
'Easy',10,25,4,320,22,15,18,'{"dinner","korean","stew","spicy","comfort food"}',false,
'https://images.unsplash.com/photo-1498654896293-37aacf113fd9?w=800',
'[{"item":"aged kimchi","amount":"2 cups"},{"item":"pork belly","amount":"200g"},{"item":"firm tofu","amount":"1 block"},{"item":"gochugaru","amount":"1 tbsp"},{"item":"garlic","amount":"4 cloves"},{"item":"green onions","amount":"3"},{"item":"kimchi brine","amount":"1/4 cup"},{"item":"sesame oil","amount":"1 tbsp"},{"item":"water or anchovy stock","amount":"2 cups"}]',
'[{"step":1,"instruction":"Slice pork belly thinly. Cut kimchi into bite-sized pieces. Reserve kimchi brine."},{"step":2,"instruction":"Sauté pork belly in sesame oil until fat renders. Add kimchi and stir-fry 3 minutes."},{"step":3,"instruction":"Add water/stock, kimchi brine, gochugaru, and garlic. Bring to boil."},{"step":4,"instruction":"Simmer 15 minutes. Add tofu cubes and cook 5 more minutes."},{"step":5,"instruction":"Garnish with sliced green onions. Serve bubbling hot with steamed rice."}]'),

-- Vietnam
('Pho Bo','pho-bo','Vietnam','Asia','Breakfast','Aromatic beef noodle soup with rice noodles, herbs, and a deeply fragrant star anise-scented broth — Vietnam''s national dish.','Pho originated in northern Vietnam in the early 20th century, likely influenced by both Chinese and French colonial cuisines. After 1954, refugees brought it south where it evolved with more herbs and condiments. It became a UNESCO-recognized cultural treasure of Hanoi.',
'Medium',20,360,4,420,28,52,10,'{"breakfast","vietnamese","soup","noodles","beef"}',false,
'https://images.unsplash.com/photo-1582878826629-29b7ad1cdc43?w=800',
'[{"item":"beef bones","amount":"2 kg"},{"item":"beef brisket","amount":"500g"},{"item":"rice noodles","amount":"400g"},{"item":"star anise","amount":"4"},{"item":"cinnamon stick","amount":"1"},{"item":"ginger","amount":"1 large piece"},{"item":"onion","amount":"2"},{"item":"fish sauce","amount":"3 tbsp"},{"item":"bean sprouts","amount":"2 cups"},{"item":"Thai basil","amount":"1 cup"},{"item":"lime","amount":"2"},{"item":"hoisin sauce","amount":"for serving"}]',
'[{"step":1,"instruction":"Char ginger and onion over open flame until blackened. Rinse."},{"step":2,"instruction":"Boil beef bones, discard first water. Refill with fresh water, add charred ginger, onion, star anise, and cinnamon."},{"step":3,"instruction":"Simmer broth for 6 hours minimum. Add brisket during last 2 hours."},{"step":4,"instruction":"Strain broth, season with fish sauce and sugar."},{"step":5,"instruction":"Cook rice noodles. Slice brisket thinly. Assemble bowls with noodles, sliced beef, and ladle hot broth over. Serve with herbs, bean sprouts, and lime."}]'),

('Banh Mi','banh-mi','Vietnam','Asia','Lunch','A crusty French baguette filled with Vietnamese pâté, pickled vegetables, cilantro, chilies, and your choice of protein — East meets West perfection.','Banh mi is a direct product of French colonialism in Vietnam. The French introduced baguettes, but Vietnamese bakers adapted them with rice flour for a lighter, crispier crust. The filled sandwich emerged in 1950s Saigon and became a global street food icon.',
'Easy',20,10,4,380,18,42,14,'{"lunch","vietnamese","sandwich","street food","fusion"}',false,
'https://images.unsplash.com/photo-1600688640154-9619e002df30?w=800',
'[{"item":"Vietnamese baguettes","amount":"4"},{"item":"pork pâté","amount":"100g"},{"item":"grilled pork or chicken","amount":"300g"},{"item":"daikon radish","amount":"1 cup pickled"},{"item":"carrots","amount":"1 cup pickled"},{"item":"cucumber","amount":"1"},{"item":"cilantro","amount":"1 bunch"},{"item":"jalapeños","amount":"2"},{"item":"mayonnaise","amount":"4 tbsp"},{"item":"soy sauce","amount":"2 tbsp"},{"item":"maggi seasoning","amount":"1 tsp"}]',
'[{"step":1,"instruction":"Quick-pickle daikon and carrots in rice vinegar, sugar, and salt for 30 minutes."},{"step":2,"instruction":"Grill or pan-fry marinated pork/chicken until cooked through."},{"step":3,"instruction":"Toast baguettes until crispy outside but soft inside."},{"step":4,"instruction":"Spread pâté on one side, mayonnaise on the other."},{"step":5,"instruction":"Layer meat, pickled vegetables, cucumber, cilantro, and jalapeño slices."}]'),

-- Turkey
('Turkish Breakfast Spread','turkish-breakfast','Turkey','Asia','Breakfast','A lavish communal breakfast (kahvaltı) featuring cheeses, olives, eggs, honey, bread, and Turkish tea — a cultural institution.','Turkish breakfast (kahvaltı, literally "before coffee") is considered a social ritual. The elaborate weekend breakfast tradition has been recognized by UNESCO as an intangible cultural heritage. Turkish people spend hours over breakfast, especially on weekends.',
'Easy',20,10,4,650,22,55,38,'{"breakfast","turkish","communal","traditional","mediterranean"}',false,
'https://images.unsplash.com/photo-1525184782196-8e2ded604bf7?w=800',
'[{"item":"beyaz peynir (white cheese)","amount":"200g"},{"item":"kaşar cheese","amount":"150g"},{"item":"olives (black and green)","amount":"1 cup"},{"item":"tomatoes","amount":"3"},{"item":"cucumbers","amount":"2"},{"item":"eggs","amount":"4"},{"item":"honey with kaymak","amount":"100g"},{"item":"Turkish bread (simit or pide)","amount":"4 pieces"},{"item":"butter","amount":"50g"},{"item":"Turkish tea","amount":"for serving"},{"item":"sucuk (Turkish sausage)","amount":"150g"}]',
'[{"step":1,"instruction":"Arrange cheeses, olives, sliced tomatoes, and cucumbers on a large platter."},{"step":2,"instruction":"Fry eggs and sucuk slices in butter (menemen style optional)."},{"step":3,"instruction":"Set out honey with kaymak, jams, and butter in small bowls."},{"step":4,"instruction":"Toast bread and brew Turkish tea in a çaydanlık."},{"step":5,"instruction":"Serve everything family-style at a large table. Enjoy over 1-2 hours."}]'),

('Kebab','adana-kebab','Turkey','Asia','Dinner','Hand-minced lamb kebab seasoned with Urfa pepper and grilled over charcoal — Adana''s fiery contribution to world cuisine.','Adana kebab is named after the southern Turkish city of Adana. The kebab tradition spans thousands of years in Anatolia. Adana kebab specifically requires hand-minced meat (not machine-ground) and tail fat, grilled on wide flat skewers over charcoal.',
'Medium',30,15,4,450,32,8,32,'{"dinner","turkish","kebab","grilled","meat"}',false,
'https://images.unsplash.com/photo-1599487488170-d11ec9c172f0?w=800',
'[{"item":"lamb shoulder","amount":"800g"},{"item":"lamb tail fat","amount":"100g"},{"item":"Urfa pepper flakes","amount":"2 tbsp"},{"item":"Aleppo pepper","amount":"1 tbsp"},{"item":"onion","amount":"1"},{"item":"salt","amount":"2 tsp"},{"item":"sumac","amount":"for serving"},{"item":"flatbread","amount":"4"},{"item":"grilled tomatoes and peppers","amount":"for serving"}]',
'[{"step":1,"instruction":"Hand-mince lamb and tail fat very finely (or use coarse grind). Do not use a food processor."},{"step":2,"instruction":"Mix meat with grated onion, Urfa pepper, Aleppo pepper, and salt. Knead for 10 minutes until sticky."},{"step":3,"instruction":"Mold meat onto wide flat skewers in long, flat shapes."},{"step":4,"instruction":"Grill over hot charcoal, turning frequently, for 8-10 minutes."},{"step":5,"instruction":"Serve on flatbread with grilled vegetables, sumac onions, and parsley."}]'),

-- ===== EUROPE =====
-- Italy
('Carbonara','pasta-carbonara','Italy','Europe','Dinner','Silky Roman pasta with guanciale, egg yolks, Pecorino Romano, and black pepper — the iconic Roman pasta perfected over generations.','Carbonara''s origins are debated. Some link it to charcoal workers (carbonari) in the Apennine mountains, others to post-WWII Rome when American soldiers brought bacon and eggs. The modern recipe was codified in Roman trattorias in the 1950s.',
'Medium',10,15,4,520,22,58,22,'{"dinner","italian","pasta","roman","classic"}',false,
'https://images.unsplash.com/photo-1612874742237-6526221588e3?w=800',
'[{"item":"spaghetti or rigatoni","amount":"400g"},{"item":"guanciale","amount":"200g"},{"item":"egg yolks","amount":"6"},{"item":"Pecorino Romano","amount":"100g grated"},{"item":"black pepper","amount":"2 tsp freshly ground"},{"item":"salt","amount":"for pasta water"}]',
'[{"step":1,"instruction":"Cut guanciale into thick strips. Cook slowly in a dry pan until fat renders and meat is crispy."},{"step":2,"instruction":"Whisk egg yolks with grated Pecorino and generous black pepper."},{"step":3,"instruction":"Cook pasta in heavily salted water until al dente. Reserve 1 cup pasta water."},{"step":4,"instruction":"Add drained pasta to guanciale pan (off heat). Toss to coat in rendered fat."},{"step":5,"instruction":"Add egg-cheese mixture, tossing vigorously. Add splashes of pasta water until creamy. Serve immediately with extra Pecorino and pepper."}]'),

('Margherita Pizza','pizza-margherita','Italy','Europe','Lunch','The original Neapolitan pizza with San Marzano tomatoes, fresh mozzarella, basil, and olive oil — pizza in its purest form.','Pizza Margherita was allegedly created in 1889 by pizzaiolo Raffaele Esposito for Queen Margherita of Italy, using ingredients representing the Italian flag: red tomato, white mozzarella, green basil. Neapolitan pizza-making is a UNESCO Intangible Cultural Heritage.',
'Medium',120,5,4,270,12,35,9,'{"lunch","italian","pizza","neapolitan","classic"}',false,
'https://images.unsplash.com/photo-1574071318508-1cdbab80d002?w=800',
'[{"item":"tipo 00 flour","amount":"500g"},{"item":"water","amount":"325ml"},{"item":"fresh yeast","amount":"3g"},{"item":"salt","amount":"10g"},{"item":"San Marzano tomatoes","amount":"400g"},{"item":"fresh mozzarella di bufala","amount":"250g"},{"item":"fresh basil","amount":"12 leaves"},{"item":"extra virgin olive oil","amount":"2 tbsp"}]',
'[{"step":1,"instruction":"Mix flour, water, yeast, and salt. Knead 15 minutes until smooth. Rest dough 24 hours in fridge."},{"step":2,"instruction":"Crush San Marzano tomatoes by hand with salt."},{"step":3,"instruction":"Divide dough into 4 balls. Stretch each by hand (never use a rolling pin) into 12-inch rounds."},{"step":4,"instruction":"Top with crushed tomatoes, torn mozzarella."},{"step":5,"instruction":"Bake at highest oven temperature (ideally 450°C/850°F) for 60-90 seconds. Add basil and olive oil after baking."}]'),

('Tiramisu','tiramisu','Italy','Europe','Desserts','Layers of espresso-soaked ladyfingers and mascarpone cream dusted with cocoa — Italy''s most famous dessert worldwide.','Tiramisu (meaning "pick me up") likely originated in Treviso, Veneto in the 1960s-70s. Le Beccherie restaurant and its chef Roberto Linguanotto are most commonly credited. The dessert quickly spread throughout Italy and became a global phenomenon.',
'Easy',30,0,8,380,7,32,24,'{"desserts","italian","coffee","no-bake","classic"}',false,
'https://images.unsplash.com/photo-1571877227200-a0d98ea607e9?w=800',
'[{"item":"ladyfinger biscuits (savoiardi)","amount":"300g"},{"item":"mascarpone cheese","amount":"500g"},{"item":"eggs","amount":"4"},{"item":"sugar","amount":"100g"},{"item":"strong espresso","amount":"300ml cooled"},{"item":"cocoa powder","amount":"for dusting"},{"item":"Marsala wine (optional)","amount":"2 tbsp"}]',
'[{"step":1,"instruction":"Separate eggs. Beat yolks with sugar until pale and thick."},{"step":2,"instruction":"Fold mascarpone into yolk mixture until smooth."},{"step":3,"instruction":"Whip egg whites to stiff peaks and gently fold into mascarpone mixture."},{"step":4,"instruction":"Dip ladyfingers briefly in espresso (don''t soak). Layer in dish, then spread mascarpone cream. Repeat layers."},{"step":5,"instruction":"Refrigerate minimum 6 hours (overnight is best). Dust generously with cocoa before serving."}]'),

-- France
('Croissant','french-croissant','France','Europe','Breakfast','Golden, buttery, flaky layered pastry — the symbol of French breakfast culture and the pinnacle of viennoiserie.','Despite its association with France, the croissant evolved from the Austrian kipferl. French bakers adapted it with laminated dough (layers of butter and dough) in the early 1900s. August Zang is credited with bringing the Viennese pastry to Paris in 1838.',
'Hard',180,20,12,240,5,26,14,'{"breakfast","french","pastry","baking","classic"}',false,
'https://images.unsplash.com/photo-1555507036-ab1f4038024a?w=800',
'[{"item":"all-purpose flour","amount":"500g"},{"item":"unsalted butter (cold)","amount":"280g"},{"item":"whole milk","amount":"300ml"},{"item":"sugar","amount":"50g"},{"item":"salt","amount":"10g"},{"item":"instant yeast","amount":"10g"},{"item":"egg (for wash)","amount":"1"}]',
'[{"step":1,"instruction":"Make détrempe: mix flour, sugar, salt, yeast, and milk. Knead lightly. Refrigerate 1 hour."},{"step":2,"instruction":"Pound cold butter into a flat square. Enclose in dough, and perform 3 sets of double turns, chilling 30 min between each."},{"step":3,"instruction":"Roll dough to 5mm thickness. Cut into triangles and roll up from base to tip."},{"step":4,"instruction":"Proof at room temperature for 2 hours until doubled."},{"step":5,"instruction":"Brush with egg wash. Bake at 200°C for 15-18 minutes until deeply golden."}]'),

('Coq au Vin','coq-au-vin','France','Europe','Dinner','Chicken braised in Burgundy wine with mushrooms, pearl onions, and lardons — the quintessential French country dish.','Coq au vin has ancient origins — legend attributes it to Julius Caesar. The modern version was popularized by Auguste Escoffier and later Julia Child, whose 1961 cookbook brought this peasant dish to international fame.',
'Medium',30,90,6,520,38,12,28,'{"dinner","french","braised","wine","classic"}',false,
'https://images.unsplash.com/photo-1600891964092-4316c288032e?w=800',
'[{"item":"chicken pieces","amount":"1.5 kg"},{"item":"red Burgundy wine","amount":"750ml"},{"item":"lardons","amount":"200g"},{"item":"pearl onions","amount":"250g"},{"item":"mushrooms","amount":"250g"},{"item":"carrots","amount":"2"},{"item":"garlic","amount":"4 cloves"},{"item":"thyme and bay leaves","amount":"bouquet garni"},{"item":"flour","amount":"2 tbsp"},{"item":"butter","amount":"3 tbsp"},{"item":"cognac","amount":"3 tbsp"}]',
'[{"step":1,"instruction":"Marinate chicken in wine with carrots, onion, and herbs overnight."},{"step":2,"instruction":"Remove chicken, pat dry. Brown in butter on all sides. Flambé with cognac."},{"step":3,"instruction":"Render lardons, sauté mushrooms and pearl onions separately. Set aside."},{"step":4,"instruction":"Dust chicken with flour, add strained marinade. Simmer covered for 1.5 hours."},{"step":5,"instruction":"Add lardons, mushrooms, and onions. Simmer 15 more minutes. Adjust seasoning and serve with crusty bread."}]'),

('Crème Brûlée','creme-brulee','France','Europe','Desserts','Silky vanilla custard with a shatteringly crisp caramelized sugar crust — France''s most elegant dessert.','Crème brûlée''s origins are disputed between France, England, and Spain. The French version became definitive in the late 17th century. The name means "burnt cream." It became a restaurant staple in the 1980s fine dining boom.',
'Medium',15,45,6,380,5,30,26,'{"desserts","french","custard","vanilla","elegant"}',false,
'https://images.unsplash.com/photo-1470124182917-cc6e71b22ecc?w=800',
'[{"item":"heavy cream","amount":"600ml"},{"item":"egg yolks","amount":"6"},{"item":"sugar","amount":"100g plus extra for torching"},{"item":"vanilla bean","amount":"1"},{"item":"pinch of salt","amount":""}]',
'[{"step":1,"instruction":"Heat cream with split vanilla bean until just simmering. Remove from heat, steep 15 minutes."},{"step":2,"instruction":"Whisk egg yolks with sugar until pale. Slowly pour warm cream into yolks, whisking constantly."},{"step":3,"instruction":"Strain custard into ramekins."},{"step":4,"instruction":"Bake in water bath at 150°C for 40-45 minutes until set but jiggly in center."},{"step":5,"instruction":"Chill at least 4 hours. Before serving, sprinkle thin layer of sugar and torch until caramelized."}]'),

-- Spain
('Paella Valenciana','paella-valenciana','Spain','Europe','Lunch','Saffron-infused rice with rabbit, chicken, green beans, and snails — the original Valencian rice masterpiece.','Paella originated in Valencia in the mid-19th century among farmers and laborers who cooked rice over open fire. The original recipe used rabbit, snails, and beans — NOT seafood. Valencians are fiercely protective of the authentic recipe.',
'Hard',30,45,6,480,28,55,14,'{"lunch","spanish","rice","saffron","traditional"}',false,
'https://images.unsplash.com/photo-1534080564583-6be75777b70a?w=800',
'[{"item":"bomba or calasparra rice","amount":"400g"},{"item":"chicken pieces","amount":"500g"},{"item":"rabbit pieces","amount":"500g"},{"item":"green beans","amount":"200g"},{"item":"white beans (garrofón)","amount":"100g"},{"item":"tomato (grated)","amount":"2"},{"item":"saffron threads","amount":"1g"},{"item":"olive oil","amount":"6 tbsp"},{"item":"chicken stock","amount":"1.2L"},{"item":"rosemary","amount":"1 sprig"},{"item":"salt","amount":"to taste"}]',
'[{"step":1,"instruction":"Heat olive oil in paella pan. Brown rabbit and chicken on all sides. Push to edges."},{"step":2,"instruction":"Add green beans and sauté. Add grated tomato and cook until darkened."},{"step":3,"instruction":"Add stock, saffron, rosemary, and white beans. Boil vigorously for 20 minutes."},{"step":4,"instruction":"Distribute rice evenly across the pan (never stir again). Cook on high 7 minutes, then medium 13 minutes."},{"step":5,"instruction":"If desired, increase heat at end for socarrat (crispy bottom). Rest 5 minutes covered with cloth before serving."}]'),

('Gazpacho','gazpacho-andaluz','Spain','Europe','Lunch','A chilled Andalusian soup of raw tomatoes, peppers, cucumber, and bread — summer in a bowl.','Gazpacho''s roots trace to Roman and Moorish Andalusia, originally a bread-based soup without tomatoes (which arrived from the Americas in the 16th century). The modern tomato version became Andalusia''s signature dish and is consumed daily during Spain''s hot summers.',
'Easy',15,0,4,120,3,15,6,'{"lunch","spanish","soup","cold","summer","vegetarian"}',false,
'https://images.unsplash.com/photo-1509440159596-0249088772ff?w=800',
'[{"item":"ripe tomatoes","amount":"1 kg"},{"item":"cucumber","amount":"1"},{"item":"green pepper","amount":"1"},{"item":"stale bread","amount":"100g"},{"item":"garlic","amount":"2 cloves"},{"item":"extra virgin olive oil","amount":"80ml"},{"item":"sherry vinegar","amount":"2 tbsp"},{"item":"salt","amount":"to taste"},{"item":"water","amount":"100ml"}]',
'[{"step":1,"instruction":"Soak stale bread in water for 10 minutes."},{"step":2,"instruction":"Roughly chop tomatoes, cucumber, and pepper. Add to blender with garlic and soaked bread."},{"step":3,"instruction":"Blend until smooth. With motor running, drizzle in olive oil."},{"step":4,"instruction":"Season with vinegar and salt. Strain for extra smoothness (optional)."},{"step":5,"instruction":"Chill for at least 2 hours. Serve cold with diced vegetable garnish and a drizzle of olive oil."}]'),

-- Greece
('Moussaka','greek-moussaka','Greece','Europe','Dinner','Layered casserole of eggplant, spiced lamb, and creamy béchamel — Greece''s most celebrated oven-baked dish.','Moussaka in its modern Greek form was created by chef Nikolaos Tselementes in the 1920s, who added the French-influenced béchamel topping. The base eggplant-meat dish has Arab origins, but the Greek version became internationally iconic.',
'Medium',45,60,8,420,22,25,26,'{"dinner","greek","casserole","eggplant","lamb"}',false,
'https://images.unsplash.com/photo-1574484284002-952d92456975?w=800',
'[{"item":"eggplants","amount":"3 large"},{"item":"ground lamb","amount":"500g"},{"item":"onion","amount":"2"},{"item":"canned tomatoes","amount":"400g"},{"item":"cinnamon","amount":"1 tsp"},{"item":"butter","amount":"60g"},{"item":"flour","amount":"60g"},{"item":"milk","amount":"600ml"},{"item":"nutmeg","amount":"1/2 tsp"},{"item":"egg yolks","amount":"2"},{"item":"Parmesan or kefalotyri","amount":"80g"}]',
'[{"step":1,"instruction":"Slice eggplants, salt and rest 30 minutes to draw out moisture. Pat dry and brush with olive oil. Grill or roast until golden."},{"step":2,"instruction":"Brown lamb with onions, add tomatoes, cinnamon, and oregano. Simmer 20 minutes."},{"step":3,"instruction":"Make béchamel: melt butter, whisk in flour, gradually add milk. Season with nutmeg. Off heat, stir in egg yolks and cheese."},{"step":4,"instruction":"Layer: eggplant, meat sauce, eggplant, meat sauce, béchamel on top."},{"step":5,"instruction":"Bake at 180°C for 45 minutes until golden and bubbling. Rest 20 minutes before cutting."}]'),

-- ===== SOUTH AMERICA =====
-- Mexico
('Tacos al Pastor','tacos-al-pastor','Mexico','North America','Dinner','Marinated pork carved from a vertical spit, served in corn tortillas with pineapple, cilantro, and salsa — Mexico City''s street food crown jewel.','Tacos al pastor were created by Lebanese immigrants to Mexico in the 1930s-40s who adapted shawarma (vertical spit cooking) using Mexican chilies and pork instead of lamb. The addition of pineapple made it distinctly Mexican.',
'Medium',240,15,6,350,22,28,16,'{"dinner","mexican","street food","pork","tacos"}',false,
'https://images.unsplash.com/photo-1551504734-5ee1c4a1479b?w=800',
'[{"item":"pork shoulder","amount":"1 kg"},{"item":"dried guajillo chilies","amount":"6"},{"item":"dried ancho chilies","amount":"3"},{"item":"pineapple","amount":"1/2"},{"item":"achiote paste","amount":"2 tbsp"},{"item":"white vinegar","amount":"3 tbsp"},{"item":"garlic","amount":"4 cloves"},{"item":"corn tortillas","amount":"24 small"},{"item":"white onion","amount":"1 diced"},{"item":"cilantro","amount":"1 bunch"},{"item":"limes","amount":"4"}]',
'[{"step":1,"instruction":"Toast and rehydrate dried chilies. Blend with achiote paste, vinegar, garlic, and pineapple juice into a smooth marinade."},{"step":2,"instruction":"Slice pork thinly, coat with marinade. Refrigerate at least 4 hours (overnight best)."},{"step":3,"instruction":"Stack marinated pork on a vertical spit with pineapple slices between layers. (Or grill/broil in oven.)"},{"step":4,"instruction":"Carve thin slices as edges crisp. Warm corn tortillas."},{"step":5,"instruction":"Serve in double tortillas with diced onion, cilantro, pineapple chunks, and lime wedges."}]'),

('Guacamole','authentic-guacamole','Mexico','North America','Appetizers & Snacks','Fresh avocado dip with lime, cilantro, onion, and serrano chili — an ancient Aztec creation still beloved worldwide.','Guacamole (from Nahuatl āhuacamōlli, "avocado sauce") was first made by the Aztecs in the 16th century. Spanish conquistadors documented it and brought avocados to Europe. The recipe has remained remarkably unchanged for 500 years.',
'Easy',10,0,4,220,3,12,18,'{"appetizers","mexican","avocado","dip","traditional"}',false,
'https://images.unsplash.com/photo-1523049673857-eb18f1d7b578?w=800',
'[{"item":"ripe avocados","amount":"3"},{"item":"lime juice","amount":"2 tbsp"},{"item":"white onion","amount":"1/4 cup diced"},{"item":"serrano chili","amount":"1"},{"item":"cilantro","amount":"1/4 cup chopped"},{"item":"tomato","amount":"1 small diced"},{"item":"salt","amount":"to taste"}]',
'[{"step":1,"instruction":"Halve avocados, remove pits. Scoop flesh into a molcajete or bowl."},{"step":2,"instruction":"Add lime juice and salt. Mash to desired consistency (chunky is traditional)."},{"step":3,"instruction":"Fold in diced onion, minced serrano, tomato, and cilantro."},{"step":4,"instruction":"Taste and adjust lime and salt. Serve immediately with tortilla chips."}]'),

-- Brazil
('Feijoada','feijoada','Brazil','South America','Lunch','A hearty black bean stew with various pork cuts, served with rice, collard greens, and farofa — Brazil''s national dish.','Feijoada''s origins are debated. The romantic story credits enslaved Africans who combined discarded pork parts with beans. More likely, it evolved from Portuguese cozido. Regardless, feijoada became Brazil''s most important communal dish, traditionally served on Wednesdays and Saturdays.',
'Medium',30,180,8,680,42,55,30,'{"lunch","brazilian","beans","pork","traditional"}',false,
'https://images.unsplash.com/photo-1623428187969-5da2dcea5ebf?w=800',
'[{"item":"black beans","amount":"500g dried"},{"item":"pork ribs","amount":"500g"},{"item":"smoked sausage (linguiça)","amount":"300g"},{"item":"pork shoulder","amount":"400g"},{"item":"bacon","amount":"200g"},{"item":"garlic","amount":"6 cloves"},{"item":"onions","amount":"2"},{"item":"bay leaves","amount":"4"},{"item":"orange","amount":"2"},{"item":"collard greens","amount":"for serving"},{"item":"farofa","amount":"for serving"},{"item":"white rice","amount":"for serving"}]',
'[{"step":1,"instruction":"Soak black beans overnight. Drain and add to large pot with fresh water."},{"step":2,"instruction":"Add pork ribs, sausage, pork shoulder, bacon, bay leaves, and whole orange. Bring to boil, then simmer."},{"step":3,"instruction":"Cook for 3 hours until beans are very tender and broth is thick."},{"step":4,"instruction":"Sauté garlic and onions, add some mashed beans to thicken the stew."},{"step":5,"instruction":"Serve with white rice, sautéed collard greens, farofa (toasted cassava flour), and orange slices."}]'),

('Caipirinha','caipirinha','Brazil','South America','Drinks','Brazil''s national cocktail made with cachaça, lime, and sugar — simple, refreshing, and dangerously delicious.','Caipirinha originated in São Paulo state in the early 20th century. Cachaça, the sugarcane spirit, has been produced in Brazil since the 1500s. The cocktail gained international fame during the 2014 World Cup and 2016 Olympics hosted by Brazil.',
'Easy',5,0,1,220,0,20,0,'{"drinks","brazilian","cocktail","cachaça","refreshing"}',false,
'https://images.unsplash.com/photo-1541546006121-e8e0d0ce0d5b?w=800',
'[{"item":"cachaça","amount":"60ml"},{"item":"lime","amount":"1"},{"item":"sugar","amount":"2 tsp"},{"item":"crushed ice","amount":"1 cup"}]',
'[{"step":1,"instruction":"Cut lime into wedges, place in a sturdy glass."},{"step":2,"instruction":"Add sugar and muddle vigorously to release lime juice and oils."},{"step":3,"instruction":"Fill glass with crushed ice."},{"step":4,"instruction":"Pour cachaça over ice and stir well. Serve immediately."}]'),

-- Peru
('Ceviche','peruvian-ceviche','Peru','South America','Lunch','Fresh fish cured in lime juice with aji amarillo, red onion, and cilantro — Peru''s national dish and culinary pride.','Ceviche dates back 2,000 years to the Moche civilization in Peru. The modern version using citrus was influenced by Spanish colonizers who brought limes. Peru declared ceviche a National Heritage dish in 2004 and celebrates National Ceviche Day on June 28.',
'Easy',20,0,4,180,22,8,4,'{"lunch","peruvian","seafood","raw","traditional"}',false,
'https://images.unsplash.com/photo-1535399831218-d5bd36d1a6b3?w=800',
'[{"item":"fresh white fish (corvina or sea bass)","amount":"500g"},{"item":"lime juice","amount":"1 cup"},{"item":"red onion","amount":"1 thinly sliced"},{"item":"aji amarillo paste","amount":"1 tbsp"},{"item":"cilantro","amount":"1/2 cup"},{"item":"garlic","amount":"1 clove minced"},{"item":"salt","amount":"to taste"},{"item":"sweet potato","amount":"1 boiled"},{"item":"corn on the cob","amount":"2 boiled"}]',
'[{"step":1,"instruction":"Cut fish into 2cm cubes. Place in a non-reactive bowl."},{"step":2,"instruction":"Add lime juice, garlic, and aji amarillo paste. The acid will ''cook'' the fish."},{"step":3,"instruction":"Let sit for 10-15 minutes only (Peruvian style is brief)."},{"step":4,"instruction":"Add sliced red onion, cilantro, and salt."},{"step":5,"instruction":"Serve immediately with sliced boiled sweet potato and choclo (large kernel corn). The citrus liquid (leche de tigre) is served as a shot."}]'),

-- Argentina
('Empanadas','empanadas-argentinas','Argentina','South America','Lunch','Golden baked or fried pastry turnovers filled with spiced beef, olives, and hard-boiled egg — Argentina''s beloved handheld meal.','Empanadas came to Argentina via Spanish colonizers who inherited them from the Moors. Each Argentine province has its own signature empanada — Tucumán''s are considered the gold standard. The Fiesta Nacional de la Empanada celebrates this cultural icon annually.',
'Medium',45,25,12,280,12,22,16,'{"lunch","argentinian","pastry","beef","baked"}',false,
'https://images.unsplash.com/photo-1604467707321-70d009801bf4?w=800',
'[{"item":"flour","amount":"500g"},{"item":"butter or lard","amount":"150g"},{"item":"warm water","amount":"200ml"},{"item":"ground beef","amount":"400g"},{"item":"onions","amount":"3"},{"item":"cumin","amount":"2 tsp"},{"item":"paprika","amount":"2 tsp"},{"item":"green olives","amount":"12"},{"item":"hard-boiled eggs","amount":"3"},{"item":"raisins","amount":"2 tbsp"},{"item":"egg wash","amount":"1 egg"}]',
'[{"step":1,"instruction":"Make dough: mix flour, melted butter, salt, and warm water. Knead until smooth, rest 30 minutes."},{"step":2,"instruction":"Cook beef with diced onions, cumin, paprika, and chili flakes. Cool completely."},{"step":3,"instruction":"Add chopped olives, diced hard-boiled egg, and raisins to cooled filling."},{"step":4,"instruction":"Roll dough, cut circles. Fill each with 2 tablespoons of filling. Fold and crimp edges (repulgue)."},{"step":5,"instruction":"Brush with egg wash. Bake at 200°C for 20-25 minutes until golden."}]'),

-- Colombia
('Arepas','arepas-colombianas','Colombia','South America','Breakfast','Grilled corn cakes made from pre-cooked cornmeal — Colombia''s daily bread and the foundation of every meal.','Arepas predate the arrival of Europeans, created by indigenous peoples of Colombia and Venezuela. The word comes from the Cumanagoto language. Arepas have been the staple food of the region for over 3,000 years and remain essential to Colombian identity.',
'Easy',10,15,6,220,6,35,6,'{"breakfast","colombian","corn","grilled","staple"}',false,
'https://images.unsplash.com/photo-1599750469882-0cf1e159c3b1?w=800',
'[{"item":"pre-cooked white cornmeal (masarepa)","amount":"2 cups"},{"item":"warm water","amount":"2.5 cups"},{"item":"salt","amount":"1 tsp"},{"item":"butter","amount":"1 tbsp"},{"item":"mozzarella cheese (for filling)","amount":"200g"}]',
'[{"step":1,"instruction":"Mix cornmeal, warm water, salt, and butter. Knead until smooth dough forms with no cracks."},{"step":2,"instruction":"Divide into 6 balls. Flatten each into thick discs about 1cm thick."},{"step":3,"instruction":"Cook on a hot griddle or grill for 5-6 minutes each side until a golden crust forms."},{"step":4,"instruction":"Optionally split open and stuff with cheese, beans, or meat."},{"step":5,"instruction":"Serve warm as breakfast or snack."}]'),

-- ===== NORTH AMERICA (USA & Caribbean) =====
('Southern Fried Chicken','southern-fried-chicken','United States','North America','Dinner','Crispy, seasoned fried chicken with a golden crust — America''s most iconic comfort food with deep African American roots.','Fried chicken in America has roots in West African and Scottish cooking traditions. Enslaved West Africans brought deep-frying techniques and seasonings that transformed the dish. It became a cornerstone of African American cuisine and Southern food culture.',
'Medium',30,25,6,480,32,20,30,'{"dinner","american","fried","chicken","comfort food"}',false,
'https://images.unsplash.com/photo-1626645738196-c2a7c87a8f58?w=800',
'[{"item":"chicken pieces","amount":"1.5 kg"},{"item":"buttermilk","amount":"2 cups"},{"item":"all-purpose flour","amount":"2 cups"},{"item":"paprika","amount":"2 tsp"},{"item":"garlic powder","amount":"1 tsp"},{"item":"cayenne pepper","amount":"1/2 tsp"},{"item":"salt and pepper","amount":"to taste"},{"item":"vegetable oil for frying","amount":"enough to fill pot 3 inches"}]',
'[{"step":1,"instruction":"Soak chicken in buttermilk with salt for at least 4 hours (overnight preferred)."},{"step":2,"instruction":"Mix flour with paprika, garlic powder, cayenne, salt, and pepper."},{"step":3,"instruction":"Remove chicken from buttermilk, dredge in seasoned flour, pressing firmly."},{"step":4,"instruction":"Heat oil to 170°C. Fry chicken in batches for 12-15 minutes, turning once, until golden and internal temp reaches 74°C."},{"step":5,"instruction":"Drain on wire rack. Rest 5 minutes before serving."}]'),

('New York Cheesecake','new-york-cheesecake','United States','North America','Desserts','Dense, creamy, tangy cheesecake with a graham cracker crust — the original and most imitated American dessert.','New York-style cheesecake was popularized by Arnold Reuben at his restaurant in the 1920s, and later perfected by Junior''s in Brooklyn (1950). The key difference from other cheesecakes is the use of heavy cream for extra richness and density.',
'Medium',20,65,12,410,7,32,28,'{"desserts","american","cheesecake","baking","classic"}',false,
'https://images.unsplash.com/photo-1524351199678-941a58a3df50?w=800',
'[{"item":"cream cheese","amount":"900g"},{"item":"sugar","amount":"200g"},{"item":"heavy cream","amount":"120ml"},{"item":"sour cream","amount":"80ml"},{"item":"eggs","amount":"5"},{"item":"vanilla extract","amount":"2 tsp"},{"item":"lemon zest","amount":"1 lemon"},{"item":"flour","amount":"3 tbsp"},{"item":"graham crackers","amount":"250g"},{"item":"butter (melted)","amount":"80g"}]',
'[{"step":1,"instruction":"Crush graham crackers, mix with melted butter. Press into springform pan bottom. Bake 10 min at 175°C."},{"step":2,"instruction":"Beat cream cheese until smooth. Add sugar gradually. Mix in eggs one at a time."},{"step":3,"instruction":"Add cream, sour cream, vanilla, lemon zest, and flour. Mix until just combined."},{"step":4,"instruction":"Pour over crust. Bake at 175°C for 55-65 minutes until edges set but center jiggles slightly."},{"step":5,"instruction":"Turn off oven, crack door open, let cool inside for 1 hour. Refrigerate overnight before serving."}]'),

-- Caribbean
('Jerk Chicken','jamaican-jerk-chicken','Jamaica','North America','Dinner','Fiery, aromatic chicken marinated in Scotch bonnet peppers, allspice, thyme, and grilled over pimento wood — Jamaica''s greatest culinary gift.','Jerk cooking originated with the Maroons, escaped enslaved Africans who fled to Jamaica''s Blue Mountains. They adapted Taino smoking techniques with African spicing traditions. The word "jerk" likely comes from the Quechua word "charqui" (dried meat).',
'Medium',30,45,6,380,35,8,22,'{"dinner","jamaican","grilled","spicy","caribbean"}',false,
'https://images.unsplash.com/photo-1532550907401-a500c9a57435?w=800',
'[{"item":"chicken pieces","amount":"1.5 kg"},{"item":"Scotch bonnet peppers","amount":"3"},{"item":"allspice (pimento) berries","amount":"2 tbsp"},{"item":"fresh thyme","amount":"6 sprigs"},{"item":"garlic","amount":"6 cloves"},{"item":"ginger","amount":"2 tbsp"},{"item":"green onions","amount":"6"},{"item":"soy sauce","amount":"3 tbsp"},{"item":"lime juice","amount":"3 tbsp"},{"item":"brown sugar","amount":"2 tbsp"},{"item":"cinnamon","amount":"1 tsp"},{"item":"nutmeg","amount":"1/2 tsp"}]',
'[{"step":1,"instruction":"Blend Scotch bonnets, allspice, thyme, garlic, ginger, green onions, soy sauce, lime juice, and sugar into a paste."},{"step":2,"instruction":"Score chicken deeply. Coat thoroughly with jerk paste. Marinate 12-24 hours."},{"step":3,"instruction":"Grill over medium-low heat (traditionally over pimento wood) for 35-45 minutes, turning occasionally."},{"step":4,"instruction":"Baste with extra marinade during cooking."},{"step":5,"instruction":"Serve with rice and peas, festival dumplings, and coleslaw."}]'),

('Rum Punch','caribbean-rum-punch','Caribbean','North America','Drinks','A tropical fruit and rum cocktail following the Caribbean''s famous 1-2-3-4 formula — pure island paradise in a glass.','Caribbean rum punch follows an old rhyme: "One of sour, two of sweet, three of strong, four of weak." Rum has been produced in the Caribbean since the 17th century when enslaved people discovered that molasses could be fermented.',
'Easy',5,0,4,240,0,28,0,'{"drinks","caribbean","cocktail","rum","tropical"}',false,
'https://images.unsplash.com/photo-1536935338788-846bb9981813?w=800',
'[{"item":"dark rum","amount":"180ml"},{"item":"lime juice","amount":"60ml"},{"item":"simple syrup","amount":"120ml"},{"item":"pineapple juice","amount":"240ml"},{"item":"orange juice","amount":"120ml"},{"item":"Angostura bitters","amount":"4 dashes"},{"item":"freshly grated nutmeg","amount":"for garnish"},{"item":"ice","amount":"plenty"}]',
'[{"step":1,"instruction":"Combine lime juice (sour), simple syrup (sweet), rum (strong), and fruit juices (weak) in a pitcher."},{"step":2,"instruction":"Add Angostura bitters and stir well."},{"step":3,"instruction":"Fill glasses with ice and pour punch over."},{"step":4,"instruction":"Garnish with freshly grated nutmeg and a lime wheel."}]'),

-- ===== OCEANIA =====
('Pavlova','pavlova','Australia','Oceania','Desserts','A crisp meringue shell with a marshmallow center, topped with whipped cream and fresh fruits — the iconic Antipodean celebration dessert.','Pavlova was created in the 1920s to honor Russian ballerina Anna Pavlova during her tour of Australia and New Zealand. Both countries claim its invention. The dessert became the centerpiece of Christmas celebrations in the Southern Hemisphere.',
'Medium',20,90,8,320,4,42,14,'{"desserts","australian","meringue","celebration","fruit"}',false,
'https://images.unsplash.com/photo-1464305795204-6f5bbfc7fb81?w=800',
'[{"item":"egg whites","amount":"6"},{"item":"caster sugar","amount":"300g"},{"item":"cornstarch","amount":"2 tsp"},{"item":"white vinegar","amount":"1 tsp"},{"item":"vanilla extract","amount":"1 tsp"},{"item":"heavy cream","amount":"300ml"},{"item":"mixed berries","amount":"2 cups"},{"item":"passionfruit","amount":"3"},{"item":"kiwi fruit","amount":"2"}]',
'[{"step":1,"instruction":"Beat egg whites until stiff peaks. Gradually add sugar, beating until glossy and thick."},{"step":2,"instruction":"Fold in cornstarch, vinegar, and vanilla."},{"step":3,"instruction":"Shape into a round on lined baking tray with slight crater in center."},{"step":4,"instruction":"Bake at 120°C for 90 minutes. Turn off oven, leave inside with door ajar until completely cool."},{"step":5,"instruction":"Top with whipped cream, fresh berries, sliced kiwi, and passionfruit pulp."}]'),

('Meat Pie','australian-meat-pie','Australia','Oceania','Lunch','A golden pastry shell filled with seasoned minced beef in rich gravy — Australia''s unofficial national dish eaten at every footy game.','The Australian meat pie evolved from British pie traditions but became distinctly Australian in the early 20th century. An estimated 270 million meat pies are consumed annually in Australia. It''s the quintessential footy food and bakery staple.',
'Medium',30,40,6,420,18,35,22,'{"lunch","australian","pastry","beef","comfort food"}',false,
'https://images.unsplash.com/photo-1583338072903-aafa69602d63?w=800',
'[{"item":"shortcrust pastry","amount":"500g"},{"item":"puff pastry","amount":"300g"},{"item":"ground beef","amount":"500g"},{"item":"onion","amount":"1 diced"},{"item":"beef stock","amount":"300ml"},{"item":"Worcestershire sauce","amount":"2 tbsp"},{"item":"tomato paste","amount":"2 tbsp"},{"item":"flour","amount":"2 tbsp"},{"item":"salt and pepper","amount":"to taste"},{"item":"egg wash","amount":"1 egg"}]',
'[{"step":1,"instruction":"Brown beef and onion. Add flour and stir. Add stock, tomato paste, and Worcestershire sauce."},{"step":2,"instruction":"Simmer until thick, about 15 minutes. Season and cool completely."},{"step":3,"instruction":"Line pie tins with shortcrust pastry."},{"step":4,"instruction":"Fill with cooled meat mixture. Top with puff pastry, crimp edges, and brush with egg wash."},{"step":5,"instruction":"Bake at 200°C for 25-30 minutes until golden. Serve with tomato sauce (ketchup)."}]'),

('Flat White','flat-white-coffee','New Zealand','Oceania','Drinks','A velvety espresso drink with microfoam milk — the Antipodean coffee innovation that conquered the world.','The flat white originated in the 1980s in either Sydney or Wellington (both cities claim it). It was created as a reaction to overly foamy cappuccinos. It conquered global coffee culture in the 2010s when Starbucks added it to their menu.',
'Easy',3,2,1,120,6,10,5,'{"drinks","new zealand","coffee","espresso","cafe"}',false,
'https://images.unsplash.com/photo-1577968897966-3d4325b36b61?w=800',
'[{"item":"espresso","amount":"double shot (60ml)"},{"item":"whole milk","amount":"180ml"}]',
'[{"step":1,"instruction":"Pull a double shot of espresso into a ceramic cup."},{"step":2,"instruction":"Steam milk to 60-65°C creating velvety microfoam (less foam than cappuccino, more than latte)."},{"step":3,"instruction":"Pour steamed milk over espresso from low height, finishing with a thin layer of microfoam."},{"step":4,"instruction":"The result should be a smooth, coffee-forward drink with a flat top of microfoam."}]'),

('Hangi','new-zealand-hangi','New Zealand','Oceania','Dinner','A traditional Māori earth oven feast where meats and vegetables are slow-cooked underground with heated volcanic stones — New Zealand''s most sacred culinary tradition.','Hangi is an ancient Māori cooking method dating back to when Polynesians first settled New Zealand around 1300 CE. The method uses geothermally heated stones in an earth pit. Hangi remains central to Māori gatherings, funerals, and celebrations.',
'Hard',60,240,12,520,35,40,18,'{"dinner","new zealand","maori","earth oven","traditional"}',false,
'https://images.unsplash.com/photo-1544025162-d76694265947?w=800',
'[{"item":"chicken","amount":"1 whole"},{"item":"lamb shoulder","amount":"1 kg"},{"item":"pork","amount":"1 kg"},{"item":"kumara (sweet potato)","amount":"6"},{"item":"potatoes","amount":"8"},{"item":"pumpkin","amount":"1/2"},{"item":"cabbage","amount":"1 head"},{"item":"stuffing","amount":"4 cups"},{"item":"water","amount":"for steam"},{"item":"volcanic stones","amount":"for heating"}]',
'[{"step":1,"instruction":"Dig a pit and heat volcanic stones in a fire for 2-3 hours until white hot."},{"step":2,"instruction":"Wrap meat and vegetables separately in tinfoil and wet cloth (traditionally flax baskets)."},{"step":3,"instruction":"Place hot stones in pit, arrange food on top. Cover with wet sacking and earth to seal steam."},{"step":4,"instruction":"Cook for 3-4 hours. The steam from the hot stones slow-cooks everything simultaneously."},{"step":5,"instruction":"Unearth carefully and serve communally. The food has a unique smoky, earthy flavor impossible to replicate."}]'),

-- More Asia
('Sushi Rolls','california-maki-sushi','Japan','Asia','Lunch','Vinegared sushi rice wrapped in nori seaweed with fresh fish and vegetables — the art of Japanese precision cuisine.','Sushi originated as a method of preserving fish in fermented rice in Southeast Asia. It evolved in Edo-period Japan (1603-1868) into nigiri sushi. The modern maki roll spread globally from the 1960s onwards.',
'Medium',30,15,4,350,12,55,6,'{"lunch","japanese","sushi","seafood","rice"}',false,
'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800',
'[{"item":"sushi rice","amount":"2 cups"},{"item":"rice vinegar","amount":"3 tbsp"},{"item":"sugar","amount":"1 tbsp"},{"item":"nori sheets","amount":"6"},{"item":"fresh salmon or tuna","amount":"200g"},{"item":"avocado","amount":"1"},{"item":"cucumber","amount":"1"},{"item":"wasabi","amount":"for serving"},{"item":"soy sauce","amount":"for serving"},{"item":"pickled ginger","amount":"for serving"}]',
'[{"step":1,"instruction":"Cook sushi rice. While hot, fold in rice vinegar, sugar, and salt. Fan to cool."},{"step":2,"instruction":"Place nori on bamboo mat. Spread rice evenly, leaving 2cm at top edge."},{"step":3,"instruction":"Lay strips of fish, avocado, and cucumber across the center."},{"step":4,"instruction":"Roll tightly using the bamboo mat, sealing the edge with water."},{"step":5,"instruction":"Slice with a wet knife into 6-8 pieces. Serve with wasabi, soy sauce, and pickled ginger."}]'),

('Satay','chicken-satay','Indonesia','Asia','Appetizers & Snacks','Grilled marinated meat skewers served with rich peanut sauce — Southeast Asia''s most beloved street food.','Satay likely originated in Java, Indonesia, inspired by Indian and Middle Eastern kebab traditions brought by Arab traders. It spread across Southeast Asia and each country developed its own variation. Indonesian satay is recognized as one of the world''s best street foods.',
'Easy',30,10,4,380,28,15,22,'{"appetizers","indonesian","grilled","peanut","street food"}',false,
'https://images.unsplash.com/photo-1529563021893-cc83c992d75d?w=800',
'[{"item":"chicken thigh","amount":"500g"},{"item":"lemongrass","amount":"2 stalks"},{"item":"turmeric","amount":"1 tsp"},{"item":"coriander","amount":"1 tsp"},{"item":"cumin","amount":"1/2 tsp"},{"item":"soy sauce","amount":"2 tbsp"},{"item":"peanut butter","amount":"1/2 cup"},{"item":"coconut milk","amount":"1/4 cup"},{"item":"chili flakes","amount":"1 tsp"},{"item":"lime juice","amount":"2 tbsp"},{"item":"bamboo skewers","amount":"20"}]',
'[{"step":1,"instruction":"Cut chicken into strips. Marinate with lemongrass, turmeric, coriander, cumin, and soy sauce for 2 hours."},{"step":2,"instruction":"Thread onto soaked bamboo skewers."},{"step":3,"instruction":"Make peanut sauce: simmer peanut butter, coconut milk, chili, lime juice, and soy sauce until thick."},{"step":4,"instruction":"Grill skewers over hot charcoal 3-4 minutes per side."},{"step":5,"instruction":"Serve with warm peanut sauce and cucumber-onion relish."}]'),

-- More Europe
('Fish and Chips','fish-and-chips','United Kingdom','Europe','Lunch','Beer-battered cod with thick-cut chips and mushy peas — Britain''s most iconic takeaway meal.','Fish and chips first appeared in Britain in the 1860s. Jewish immigrants brought fried fish traditions from Portugal/Spain, while chips (fries) came from Belgium or France. The combination became the working class staple. By 1910, there were 25,000 fish and chip shops in Britain.',
'Medium',15,20,4,680,32,65,30,'{"lunch","british","fried","seafood","takeaway"}',false,
'https://images.unsplash.com/photo-1579208030886-b1f5b6b12db8?w=800',
'[{"item":"cod fillets","amount":"4"},{"item":"flour","amount":"200g"},{"item":"beer","amount":"250ml cold"},{"item":"baking powder","amount":"1 tsp"},{"item":"large potatoes","amount":"4"},{"item":"vegetable oil for frying","amount":"2L"},{"item":"salt","amount":"generous"},{"item":"malt vinegar","amount":"for serving"},{"item":"mushy peas","amount":"for serving"},{"item":"tartar sauce","amount":"for serving"}]',
'[{"step":1,"instruction":"Cut potatoes into thick chips. Soak in cold water 30 minutes, then par-boil for 5 minutes. Drain and dry thoroughly."},{"step":2,"instruction":"First fry chips at 130°C for 8 minutes (blanch fry). Drain and rest."},{"step":3,"instruction":"Make batter: whisk flour, beer, baking powder, and salt until smooth."},{"step":4,"instruction":"Heat oil to 180°C. Dip fish in flour then batter. Fry 6-8 minutes until golden and crispy."},{"step":5,"instruction":"Second fry chips at 190°C for 3-4 minutes until golden and crispy. Serve with salt, vinegar, and mushy peas."}]'),

('Wiener Schnitzel','wiener-schnitzel','Austria','Europe','Dinner','Thinly pounded veal, breaded and fried to golden perfection — Vienna''s most famous contribution to world cuisine.','Wiener Schnitzel (Viennese cutlet) has been a Viennese culinary icon since at least the 18th century. Legend links it to Field Marshal Radetzky bringing the recipe from Milan, but this is disputed. It was declared a Protected Traditional Specialty by the EU.',
'Medium',20,10,4,450,28,25,26,'{"dinner","austrian","fried","veal","classic"}',false,
'https://images.unsplash.com/photo-1599921841143-819065a55cc6?w=800',
'[{"item":"veal cutlets","amount":"4"},{"item":"flour","amount":"100g"},{"item":"eggs","amount":"3 beaten"},{"item":"breadcrumbs","amount":"200g"},{"item":"clarified butter or lard","amount":"for frying"},{"item":"lemon wedges","amount":"4"},{"item":"salt","amount":"to taste"},{"item":"lingonberry jam","amount":"for serving"}]',
'[{"step":1,"instruction":"Pound veal cutlets very thin (3-4mm) between plastic wrap."},{"step":2,"instruction":"Season with salt. Dredge in flour, then beaten egg, then breadcrumbs. Press crumbs lightly."},{"step":3,"instruction":"Heat clarified butter in a large pan (enough to float the schnitzel)."},{"step":4,"instruction":"Fry 2-3 minutes per side, swirling the pan so the breading puffs away from the meat."},{"step":5,"instruction":"Drain on paper. Serve immediately with lemon wedges, potato salad, and lingonberry jam."}]'),

('Shakshuka','shakshuka','Israel','Asia','Breakfast','Eggs poached in a spiced tomato and pepper sauce — a beloved Middle Eastern and North African breakfast shared across cultures.','Shakshuka (meaning "a mixture") likely originated in Ottoman North Africa (Tunisia or Libya). It spread to Israel via Tunisian Jews and became a breakfast staple across the Middle East. Each region has its own variation.',
'Easy',10,20,4,280,14,16,18,'{"breakfast","middle eastern","eggs","tomato","vegetarian"}',false,
'https://images.unsplash.com/photo-1590412200988-a436970781fa?w=800',
'[{"item":"eggs","amount":"6"},{"item":"canned tomatoes","amount":"800g"},{"item":"red bell peppers","amount":"2"},{"item":"onion","amount":"1"},{"item":"garlic","amount":"4 cloves"},{"item":"cumin","amount":"2 tsp"},{"item":"paprika","amount":"2 tsp"},{"item":"chili flakes","amount":"1 tsp"},{"item":"olive oil","amount":"3 tbsp"},{"item":"feta cheese","amount":"100g crumbled"},{"item":"fresh cilantro or parsley","amount":"for garnish"},{"item":"crusty bread","amount":"for serving"}]',
'[{"step":1,"instruction":"Sauté diced onion and peppers in olive oil until soft, about 8 minutes."},{"step":2,"instruction":"Add garlic, cumin, paprika, and chili flakes. Cook 1 minute until fragrant."},{"step":3,"instruction":"Pour in crushed tomatoes, season with salt. Simmer 10 minutes until thickened."},{"step":4,"instruction":"Make wells in the sauce and crack eggs into them. Cover and cook 5-8 minutes until whites set but yolks are still runny."},{"step":5,"instruction":"Scatter feta and herbs on top. Serve in the pan with crusty bread for dipping."}]')

ON CONFLICT (slug) DO NOTHING;

